B:  Template Matching

  実際に、テンプレート画像B を平行移動させて画像A に含まれるかを調べます。まず、画像A の中における
 M × M の正方形領域とテンプレート画像B の同一判定は、二重ループで行うことが可能です。次に、画像A の
 中におけるM × M の正方形領域は何通りあるか考えます。これは(N −M + 1) × (N −M + 1) 通り考えられま
 す。以上のことから、全探索を行ったときの時間計算量はO(N 2M 2) となり、これは間に合います。
  より高速な解法として、ハッシュを用いた解法が存在します。(詳細は略)


  C++のコード例


                                                  1

 1 int main(void){

 2     int N,M;

 3     cin >> N >> M;


 4

 5     const int nmmax=50;

 6     char A[nmmax][nmmax],B[nmmax][nmmax];


 7


 8

 9     for(int y=0;y<N;++y){

10         for(int x=0;x<N;++x){

11             cin >> A[y][x];

12         }

13     }


14

15     for(int y=0;y<M;++y){

16         for(int x=0;x<M;++x){

17             cin >> B[y][x];

18         }

19     }


20

21     bool exist=false;


22

23     for(int ly=0;ly<N;++ly){

24         for(int lx=0;lx<N;++lx){

25             if(ly+M-1>=N or lx+M-1>=N) continue;


26

27             bool match=true;

28             for(int y=0;y<M;++y){

29                 for(int x=0;x<M;++x){

30                     if(A[ly+y][lx+x]!=B[y][x]) match=false;

31                 }

32             }
33             if(match) exist=true;

34         }

35     }


36

37     if(exist)

38         cout << "Yes" << endl;

39     else

40         cout << "No" << endl;


41

42     return 0;

43 }



